-- Мультимножество бизнес-полей соответствует текущему STG. Batch ID исключён; JSON payload здесь сравнивается по JSON-представлению, его точный текст дополнительно проверяется INITIAL и stage-to-ledger.
WITH stage AS (SELECT topic,kafka_partition,kafka_offset,event_json,try(json_parse(event_json)) AS j FROM {{target:oil_stg__event_log}}), expected AS (SELECT topic,kafka_partition,kafka_offset,event_json,try_cast(json_extract_scalar(j,'$.schema_version') AS integer) AS schema_version,json_extract_scalar(j,'$.event_id') AS event_id,json_extract_scalar(j,'$.event_type') AS event_type,json_extract_scalar(j,'$.entity_id') AS entity_id,try_cast(json_extract_scalar(j,'$.entity_version') AS bigint) AS entity_version,json_extract_scalar(j,'$.op') AS op,try(from_iso8601_timestamp_nanos(json_extract_scalar(j,'$.event_time'))) AS event_time,json_format(json_extract(j,'$.payload')) AS payload_json FROM stage), actual AS (SELECT topic,kafka_partition,kafka_offset,event_json,schema_version,event_id,event_type,entity_id,entity_version,op,event_time,json_format(try(json_parse(payload))) AS payload_json FROM {{target:oil_stg__v_event_parsed}}) SELECT count(*) AS n FROM ((SELECT * FROM expected EXCEPT ALL SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT ALL SELECT * FROM expected)) q;
